				findAnnotation(Builder.Default.class, fieldNode, true);
				isDefault = null;
			}

			if (fd.init == null && isDefault != null) {
				isDefault.addWarning("@Builder.Default requires an initializing expression (' = something;').");
				findAnnotation(Builder.Default.class, fieldNode, true);
